import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testPositive() {
        Assert.assertTrue("5 should be positive", isPositive(5))
    }

    @Test
    fun testNegative() {
        Assert.assertFalse("-3 should not be positive", isPositive(-3))
    }

    @Test
    fun testZero() {
        Assert.assertFalse("0 should not be positive", isPositive(0))
    }
}
